import json
from pathlib import Path
p=Path(__file__).parent/'chunks/0001.json'
d=json.loads(p.read_text())
translations={
 't000001': '1984 de George Orwell',
 't000002': '1984 de George Orwell',
 't000003': 'Capitolul întâi: Totalitarismul și controlul social',
 't000004': '''„1984” de George Orwell prezintă un portret tulburător al unei societăți totalitare în care statul controlează fiecare aspect al vieții. Acțiunea romanului se desfășoară în Oceania, un suprastat împărțit rigid în trei clase distincte. În vârf se află Partidul Interior, care cuprinde aproximativ 2% din populație. Aceștia sunt membrii elitei care dețin puterea și se bucură de privilegii relative. Sub ei se află Partidul Exterior, din care face parte protagonistul Winston Smith. Acest grup reprezintă aproximativ 13% din populație și alcătuiește aparatul birocratic al statului. La baza ierarhiei se află prolii, sau proletariatul, care reprezintă 85% din populație. Sunt ținuți în ignoranță și sărăcie și sunt în mare parte ignorați de Partid câtă vreme rămân docili.''',
 't000005': '''Deasupra acestei societăți se află figura Fratelui cel Mare, conducătorul enigmatic și poate fictiv al Partidului. Imaginea lui este omniprezentă și privește de pe afișe care poartă mesajul „FRATELE CEL MARE TE PRIVEȘTE”. Această amintire permanentă a supravegherii întărește controlul Partidului asupra cetățenilor.''',
 't000006': '''Partidul își menține puterea prin diverse mecanisme de control. Printre cele mai importante se numără teleecranele, televizoare bidirecționale aflate în fiecare locuință și spațiu public. Aceste dispozitive nu transmit doar propagandă, ci urmăresc și activitățile, ba chiar expresiile faciale ale membrilor Partidului. Teama că ar putea fi observați în orice clipă îi face pe oameni să se autocenzureze fără încetare.''',
 't000007': '''Alături de teleecrane acționează Poliția Gândirii, o forță secretă însărcinată să descopere delictul de gândire: orice gând sau faptă care contravine ortodoxiei Partidului. Simpla suspiciune poate duce la arestare, tortură și „vaporizare”, adică la ștergerea completă a unei persoane din existență și din istorie.''',
 't000008': '''Un aspect esențial al controlului Partidului este capacitatea de a manipula însăși realitatea. Aceasta se realizează mai ales prin Ministerul Adevărului, unde lucrează Winston. Aici, istoria este rescrisă permanent pentru a corespunde relatării actuale a Partidului. Faptele incomode sunt șterse, iar noi „adevăruri” sunt create. Modificarea necontenită a trecutului îi împiedică pe cetățeni să aibă încredere în propriile amintiri sau să conteste versiunea Partidului despre evenimente.''',
 't000009': '''În centrul acestei manipulări se află conceptul de dublugândit: capacitatea de a susține simultan două convingeri contradictorii. Membrii Partidului trebuie să accepte orice le spune acesta, chiar dacă intră în contradicție cu ceea ce li s-a spus ieri sau cu propriile experiențe. Această gimnastică mintală slăbește și mai mult capacitatea individului de a gândi critic sau independent.''',
 't000010': '''Partidul urmărește să elimine individualitatea sub toate formele ei. Folosește în acest scop, printre altele, haine uniforme, condiții de trai standardizate și rutine zilnice reglementate. Relațiile personale sunt descurajate, deoarece loialitatea față de Partid trebuie să primeze asupra oricărei alte legături. Chiar și gândurile și emoțiile private sunt vizate. Scopul final, așa cum apare în roman, este ca delictul de gândire să devină literalmente imposibil prin eliminarea limbajului și a conceptelor necesare formulării unor idei neortodoxe.''',
 't000011': '''Efectul cumulat al acestor mecanisme de control este profund. Cetățenii Oceaniei trăiesc într-o stare permanentă de teamă și paranoia. Încrederea aproape dispare, căci fiecare știe că până și cei mai apropiați membri ai familiei l-ar putea denunța Poliției Gândirii. Această atmosferă de suspiciune și izolare întărește și mai mult puterea Partidului. Fără sentimentul unei comunități sau al unei rezistențe împărtășite, oamenii se simt neputincioși și singuri în fața forței copleșitoare a statului.''',
 't000012': '''Erodarea relațiilor personale și a legăturilor umane autentice lasă un gol pe care Partidul îl umple cu emoții fabricate. Săptămâna Urii și cele Două Minute de Ură arată cum Partidul canalizează emoțiile firești ale oamenilor spre manifestări controlate și aprobate de stat.''',
}
assert set(translations)=={x['id'] for x in d['segments']}
for seg in d['segments']:seg['translation']=translations[seg['id']]
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('translated',len(d['segments']))
